True def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    pairs.append((r, c, dr, dc, color))

    def ray(r, c, dr, dc, color):
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w and grid[r][c] == bg:
            out[r][c] = color
            r += dr
            c += dc

    # A multi-pair motif sends rays outward from each diagonal pair.
    if len(pairs) >= 2:
        for r, c, dr, dc, color in pairs:
            ray(r, c, -dr, -dc, color)
            ray(r + dr, c + dc, dr, dc, color)

    # A diagonal pair supported by a third same-color orthogonal neighbor
    # extends away from that support.
    for r, c, dr, dc, color in pairs:
        a = (r, c)
        b = (r + dr, c + dc)
        support_a = any(0 <= r + ar < h and 0 <= c + ac < w and grid[r + ar][c + ac] == color
                        for ar, ac in ((-1, 0), (1, 0), (0, -1), (0, 1)) if (r + ar, c + ac) != b)
        support_b = any(0 <= r + dr + ar < h and 0 <= c + dc + ac < w and grid[r + dr + ar][c + dc + ac] == color
                        for ar, ac in ((-1, 0), (1, 0), (0, -1), (0, 1)) if (r + dr + ar, c + dc + ac) != a)
        if support_a and not support_b:
            ray(b[0], b[1], dr, dc, color)
        elif support_b and not support_a:
            ray(a[0], a[1], -dr, -dc, color)
    return out

